package local.m13.home;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Read-only public release discovery; installation always uses the system confirmation UI. */
public final class LauncherUpdateActivity extends Activity {
    private static java.lang.ref.WeakReference<LauncherUpdateActivity> active=new java.lang.ref.WeakReference<LauncherUpdateActivity>(null);
    public static JSONObject diagnostics()throws Exception{LauncherUpdateActivity a=active.get();return a==null?new JSONObject():new JSONObject().put("busy",a.busy).put("latest",a.release==null?"":a.release.optString("tag_name")).put("downloadEnabled",a.download.isEnabled()).put("status",a.status.getText().toString()).put("retained",new File(a.dir(),"previous.apk").isFile());}
    static final String REPO="https://github.com/QQ-L-XX/m13-light-launcher/";
    private final Handler ui=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private Button download,check;private volatile boolean destroyed;private boolean busy;private JSONObject release;private String apkUrl,expected,name;private long size;
    private int dp(int n){return TvUi.dp(this,n);}
    private File dir(){File d=new File(getFilesDir(),"updates");d.mkdirs();return d;}
    private Button button(LinearLayout root,String title,final Runnable action){Button b=new Button(this);b.setText(title);root.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){action.run();}});return b;}
    public void onCreate(Bundle b){super.onCreate(b);active=new java.lang.ref.WeakReference<LauncherUpdateActivity>(this);getWindow().setFlags(1024,1024);ScreenPolicy.applyWindow(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(64),dp(30),dp(64),dp(30));root.setBackground(BlueRedTheme.background(0));status=new TextView(this);status.setTextColor(BlueRedTheme.TEXT);status.setTextSize(17);status.setPadding(0,0,0,dp(16));ScrollView scroll=new ScrollView(this);scroll.addView(status);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));check=button(root,"检查 GitHub 更新",new Runnable(){public void run(){check();}});download=button(root,"下载并安装新版",new Runnable(){public void run(){confirmDownload();}});download.setEnabled(false);button(root,"保留当前安装包",new Runnable(){public void run(){retain();}});button(root,"打开保留的旧版安装包",new Runnable(){public void run(){previous();}});button(root,"返回设置",new Runnable(){public void run(){finish();}});setContentView(root);TvUi.inset(this);check.requestFocus();check();}
    private String version(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "未知";}}
    private void show(String text){status.setText(text);}
    private void finished(String text){busy=false;check.setEnabled(true);show(text);}
    private void check(){if(busy)return;busy=true;check.setEnabled(false);download.setEnabled(false);show("当前版本 "+version()+"\n正在检查 GitHub 正式发布…");worker.submit(new Runnable(){public void run(){try{LibreTvNet.init(LauncherUpdateActivity.this);final JSONObject r=new JSONObject(LibreTvNet.get("https://api.github.com/repos/QQ-L-XX/m13-light-launcher/releases/latest"));if(r.optBoolean("draft")||r.optBoolean("prerelease"))throw new IOException("尚无正式版本");JSONArray assets=r.getJSONArray("assets");JSONObject apk=null;String sums="";for(int n=0;n<assets.length();n++){JSONObject asset=assets.getJSONObject(n);String filename=asset.getString("name");if(filename.matches("M13-Light-Launcher-[0-9.]+\\.apk")){if(apk!=null)throw new IOException("发布包含多个安装包");apk=asset;}if(filename.equals("SHA256SUMS.txt"))sums=asset.getString("browser_download_url");}if(apk==null)throw new IOException("该版本未附安装包");final String url=apk.getString("browser_download_url"),filename=apk.getString("name");allowReleaseUrl(url);long bytes=apk.getLong("size");if(bytes<100000||bytes>100*1024*1024L)throw new IOException("安装包大小异常");String digest=apk.optString("digest","");if(digest.startsWith("sha256:"))digest=digest.substring(7);else{if(sums.isEmpty())throw new IOException("发布缺少 SHA-256 校验文件");allowReleaseUrl(sums);String text=LibreTvNet.get(sums);digest="";for(String line:text.split("\\r?\\n")){String[] parts=line.trim().split("\\s+",2);if(parts.length==2&&parts[1].replaceFirst("^\\*","").equals(filename))digest=parts[0];}}if(!digest.matches("[0-9a-fA-F]{64}"))throw new IOException("发布校验值无效");final String hash=digest.toLowerCase(Locale.US);final long length=bytes;ui.post(new Runnable(){public void run(){if(destroyed)return;release=r;apkUrl=url;expected=hash;name=filename;size=length;String tag=r.optString("tag_name");boolean newer=UpdateVersion.newer(tag,version());download.setEnabled(newer);String notes=r.optString("body");finished("当前版本 "+version()+"\nGitHub 正式版 "+tag+"\n"+(newer?"有可用更新 · "+(length/1024/1024)+" MB":"当前已是相同或更新版本，无需安装旧版")+"\n\n"+notes.substring(0,Math.min(12000,notes.length())));}});}catch(final Exception e){ui.post(new Runnable(){public void run(){if(!destroyed)finished("当前版本 "+version()+"\n检查未完成，请检查网络后重试。\n"+e.getMessage());}});}}});}
    private static void allowReleaseUrl(String value)throws Exception{URL u=new URL(value);if(!value.startsWith(REPO+"releases/download/")||!"https".equals(u.getProtocol()))throw new IOException("安装包不属于此项目的正式发布");}
    private void confirmDownload(){if(busy||release==null)return;new AlertDialog.Builder(this).setTitle("下载 "+release.optString("tag_name")+"？").setMessage("下载后核验完整性、包名、签名和版本，并保留当前安装包。安装仍需在电视上确认。").setPositiveButton("下载",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){fetch();}}).setNegativeButton("取消",null).show();}
    private void copy(File from,File to)throws Exception{File temp=new File(to.getPath()+".tmp");FileInputStream in=new FileInputStream(from);FileOutputStream out=new FileOutputStream(temp);try{byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();out.write(bytes,0,n);}out.getFD().sync();}finally{in.close();out.close();}if(!temp.renameTo(to))throw new IOException("安装包备份失败");}
    private void keepCurrent()throws Exception{File current=new File(getApplicationInfo().sourceDir);copy(current,new File(dir(),"previous.apk"));}
    private void retain(){if(busy)return;busy=true;show("正在保留当前安装包…");worker.submit(new Runnable(){public void run(){try{keepCurrent();ui.post(new Runnable(){public void run(){if(!destroyed)finished("当前安装包已保留在盒子私有目录。\n后续可打开此安装包；系统可能不允许直接降级，请勿卸载或清除数据来强行降级。");}});}catch(final Exception e){ui.post(new Runnable(){public void run(){if(!destroyed)finished("保留失败："+e.getMessage());}});}}});}
    private void fetch(){if(busy)return;busy=true;check.setEnabled(false);download.setEnabled(false);show("下载中，请保持此页面打开…");worker.submit(new Runnable(){public void run(){File part=new File(dir(),"download.part");HttpURLConnection h=null;try{h=LibreTvNet.open(apkUrl,null);if(h.getResponseCode()!=200)throw new IOException("下载返回 "+h.getResponseCode());MessageDigest digest=MessageDigest.getInstance("SHA-256");InputStream in=h.getInputStream();FileOutputStream out=new FileOutputStream(part);long count=0,last=0;try{byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();count+=n;if(count>size)throw new IOException("下载大小不符");out.write(bytes,0,n);digest.update(bytes,0,n);if(SystemClock.elapsedRealtime()-last>1000){last=SystemClock.elapsedRealtime();final long done=count;ui.post(new Runnable(){public void run(){if(!destroyed)show("正在下载 "+(done*100/size)+"%\n完成后核验签名与版本");}});}}out.getFD().sync();}finally{in.close();out.close();}if(count!=size)throw new IOException("下载不完整");StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.US,"%02x",b&255));if(!expected.equals(hash.toString()))throw new IOException("校验失败，请重新下载");validateApk(part,true);keepCurrent();final File target=new File(dir(),"download.apk");if(!part.renameTo(target))throw new IOException("安装包保存失败");ui.post(new Runnable(){public void run(){if(destroyed)return;finished("下载和校验通过，当前安装包已保留。");install(target);}});}catch(final Exception e){part.delete();ui.post(new Runnable(){public void run(){if(!destroyed){finished("下载未完成："+e.getMessage()+"\n可重新检查后重试。");}}});}finally{if(h!=null)h.disconnect();}}});}
    private void validateApk(File file,boolean newer)throws Exception{PackageManager pm=getPackageManager();PackageInfo remote=pm.getPackageArchiveInfo(file.getPath(),PackageManager.GET_SIGNATURES),local=pm.getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);if(remote==null||!getPackageName().equals(remote.packageName)||remote.signatures==null||!Arrays.equals(remote.signatures,local.signatures))throw new IOException("安装包包名或签名不匹配");if(newer&&remote.versionCode<=local.versionCode)throw new IOException("下载版本没有高于当前版本");}
    private void previous(){final File file=new File(dir(),"previous.apk");try{validateApk(file,false);}catch(Exception e){show("没有可用的旧版安装包，请先选择“保留当前安装包”。");return;}new AlertDialog.Builder(this).setTitle("打开保留的安装包？").setMessage("由系统决定是否允许安装或降级。应用数据不会自动恢复；不要卸载当前应用来绕过版本限制。").setPositiveButton("打开",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){install(file);}}).setNegativeButton("取消",null).show();}
    private void install(File file){try{Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://local.m13.home.packages/"+file.getName()),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}catch(Exception e){show("系统安装界面未能打开："+e.getMessage());}}
    protected void onDestroy(){destroyed=true;worker.shutdownNow();ui.removeCallbacksAndMessages(null);super.onDestroy();}
}
